function writeSafe(writer, data) {
  const ok = writer.write(data);
  if (!ok) {
    writer.once('drain', () => resumeWriting());
  }
}

// Safe: zero-initialized
const safe = Buffer.alloc(1024);
// Fast: must be fully overwritten before transmission!
const fast = Buffer.allocUnsafe(1024);
fast.fill(0);

